{"source": "def investigate(context, acquire):
    hist = acquire("history")

    def simulate(actions, put_mode, channel_mode, trigger):
        committed = {}
        pending = {"main": {}, "other": {}}
        in_tx = {"main": False, "other": False}
        total = {"main": 0, "other": 0}
        last_changes = {"main": 0, "other": 0}

        def visible(conn, key):
            if in_tx[conn]:
                if key in pending[conn]:
                    return pending[conn][key]
            return committed.get(key, None)

        def write(conn, key, value, is_delete):
            cur = visible(conn, key)
            direct = 0
            if is_delete:
                if cur is not None:
                    direct = 1
                    if in_tx[conn]:
                        pending[conn][key] = None
                    else:
                        del committed[key]
            else:
                if put_mode == "ignore":
                    if cur is None:
                        direct = 1
                        if in_tx[conn]:
                            pending[conn][key] = value
                        else:
                            committed[key] = value
                elif put_mode == "replace":
                    direct = 1
                    if in_tx[conn]:
                        pending[conn][key] = value
                    else:
                        committed[key] = value
                else:
                    if cur is None:
                        direct = 1
                        if in_tx[conn]:
                            pending[conn][key] = value
                        else:
                            committed[key] = value
                    elif cur != value:
                        direct = 1
                        if in_tx[conn]:
                            pending[conn][key] = value
                        else:
                            committed[key] = value
            trig = 1 if (direct and trigger) else 0
            last_changes[conn] = direct
            total[conn] += direct + trig

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = {}
            elif op == "commit":
                for k, v in pending[conn].items():
                    if v is None:
                        if k in committed:
                            del committed[k]
                    else:
                        committed[k] = v
                pending[conn] = {}
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = {}
                in_tx[conn] = False
            elif op == "put":
                write(conn, act["key"], act["value"], False)
            elif op == "update":
                key = act["key"]
                value = act["value"]
                cur = visible(conn, key)
                if cur is not None:
                    if in_tx[conn]:
                        pending[conn][key] = value
                    else:
                        committed[key] = value
                    last_changes[conn] = 1
                    total[conn] += 1
                    if trigger:
                        total[conn] += 1
                else:
                    last_changes[conn] = 0
            elif op == "delete":
                write(conn, act["key"], None, True)

        if channel_mode == "changes":
            ch = last_changes["main"]
        elif channel_mode == "total_main":
            ch = total["main"]
        else:
            ch = total["main"] + total["other"]
        return ch, len(committed), sum(committed.values())

    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for channel_mode in ["changes", "total_main", "total_both"]:
            for trigger in [False, True]:
                ok = True
                for rec in hist:
                    ch, cnt, sm = simulate(rec["actions"], put_mode, channel_mode, trigger)
                    obs = rec["observed"]
                    if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, channel_mode, trigger))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = set()
    for put_mode, channel_mode, trigger in candidates:
        ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cnt)
        elif goal == "committed_sum":
            results.add(sm)
        else:
            return {"value": None, "unresolved": True}
    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Simulates all 18 family members (3 put modes x 3 channel modes x 2 trigger states) against calibration receipts, then predicts the goal only if all consistent candidates agree.", "lesson": "The channel is main changes() (last direct row-change count), not total_changes, and put uses INSERT OR IGNORE: repeated put of same key yields channel 2 (1+1) but committed_sum 1. Trigger absent."}
